{"command":"node -e "
const start = Date.now();
const g = require('./knowledge-graph.json');
const loadMs = Date.now() - start;

// Build indexes
const ixStart = Date.now();
const attrs = g.attrs;
const nameToId = {};
for (const [id, name] of Object.entries(attrs)) nameToId[name] = parseInt(id);

const TYPE = nameToId['type'];
const STATUS = nameToId['status'];
const TITLE = nameToId['title'];
const PATH = 266;
const PARTOF = nameToId['part-of'];
const ID = nameToId['id'];
const GOAL = nameToId['goal'];

// Index by entity
const byEntity = new Map();
for (const [e, a, v, t] of g.eavt) {
  if (!byEntity.has(e)) byEntity.set(e, []);
  byEntity.get(e).push([a, v]);
}

// Query: all tasks with their status and part-of
const tasks = [];
for (const [eid, facts] of byEntity) {
  const type = facts.find(f => f[0] === TYPE);
  if (!type || type[1] !== 'task') continue;
  const title = facts.find(f => f[0] === TITLE);
  const status = facts.find(f => f[0] === STATUS);
  const partOf = facts.find(f => f[0] === PARTOF);
  const path = facts.find(f => f[0] === PATH);
  tasks.push({
    title: title ? title[1] : '?',
    status: status ? status[1] : '?',
    partOf: partOf ? partOf[1] : '?',
    path: path ? path[1] : '?',
  });
}

const queryMs = Date.now() - ixStart;
console.log('Load:', loadMs + 'ms');
console.log('Index+query:', queryMs + 'ms');
console.log('Total:', (loadMs + queryMs) + 'ms');
console.log('Tasks found:', tasks.length);
console.log('Sample:', JSON.stringify(tasks.slice(0, 3)));
// Count tasks by plan
const byPlan = {};
for (const t of tasks) {
  const plan = t.partOf;
  if (!byPlan[plan]) byPlan[plan] = {total: 0, completed: 0, open: 0};
  byPlan[plan].total++;
  if (t.status === 'completed') byPlan[plan].completed++;
  else if (t.status === 'open') byPlan[plan].open++;
}
console.log('agentic-orchestration:', JSON.stringify(byPlan['agentic-orchestration']));
"","description":"Benchmark datastore query speed"}

{"file_path":"c:\Users\emsen\research\operations\engineering\tools\agentic\hooks\datastore.js","content":"/**
 * Datastore interface — reads from knowledge-graph.json.
 *
 * The knowledge graph is an EAVT (entity-attribute-value-transaction) store
 * built by install.js from all markdown files. Hooks read this instead of
 * scanning directories and parsing frontmatter on every turn.
 *
 * When a file is written/edited, the update-datastore.js PostToolUse hook
 * patches the graph so it stays in sync.
 *
 * Usage:
 *   const ds = require('./datastore.js');
 *   const db = ds.load();
 *   const tasks = db.query({ type: 'task', status: 'open' });
 *   const plan = db.getById('agentic-orchestration');
 *   const children = db.where({ 'part-of': 'agentic-orchestration' });
 */
'use strict';

const fs = require('fs');
const path = require('path');

const REPO_ROOT = path.resolve(__dirname, '..', '..', '..', '..', '..');
const GRAPH_PATH = path.join(REPO_ROOT, 'knowledge-graph.json');

/**
 * Load and index the knowledge graph. Returns a query interface.
 */
function load() {
  const raw = JSON.parse(fs.readFileSync(GRAPH_PATH, 'utf8'));

  // Build attr name → id mapping
  const attrs = raw.attrs || {};
  const nameToId = {};
  const idToName = {};
  for (const [id, name] of Object.entries(attrs)) {
    nameToId[name] = parseInt(id);
    idToName[parseInt(id)] = name;
  }

  // Well-known attribute IDs
  const TYPE = nameToId['type'];
  const STATUS = nameToId['status'];
  const TITLE = nameToId['title'];
  const PATH = nameToId[':path'] || nameToId['path'] || 266;
  const PARTOF = nameToId['part-of'];
  const ID = nameToId['id'];
  const GOAL = nameToId['goal'];
  const DESC = nameToId['description'];
  const DEFINES = nameToId['defines'];

  // Index: entity → array of [attrId, value]
  const byEntity = new Map();
  for (const [e, a, v] of raw.eavt) {
    if (!byEntity.has(e)) byEntity.set(e, []);
    byEntity.get(e).push([a, v]);
  }

  // Helper: get entity as a plain object with named keys
  function entityToRecord(eid) {
    const facts = byEntity.get(eid);
    if (!facts) return null;
    const rec = { _eid: eid };
    for (const [a, v] of facts) {
      const name = idToName[a];
      if (name) {
        // If key already exists, make it an array
        if (rec[name] !== undefined) {
          if (!Array.isArray(rec[name])) rec[name] = [rec[name]];
          rec[name].push(v);
        } else {
          rec[name] = v;
        }
      }
    }
    return rec;
  }

  // Query: find all entities matching a filter (type, status, part-of, etc.)
  function query(filter) {
    const results = [];
    for (const [eid, facts] of byEntity) {
      let match = true;
      for (const [key, val] of Object.entries(filter)) {
        const attrId = nameToId[key];
        if (attrId === undefined) { match = false; break; }
        const fact = facts.find(f => f[0] === attrId);
        if (!fact || fact[1] !== val) { match = false; break; }
      }
      if (match) {
        results.push(entityToRecord(eid));
      }
    }
    return results;
  }

  // Get entity by id field value
  function getById(idValue) {
    for (const [eid, facts] of byEntity) {
      const idFact = facts.find(f => f[0] === ID);
      if (idFact && idFact[1] === idValue) return entityToRecord(eid);
    }
    return null;
  }

  // Get entity by path
  function getByPath(filePath) {
    const normalized = filePath.replace(/\\/g, '/');
    for (const [eid, facts] of byEntity) {
      const pathFact = facts.find(f => f[0] === PATH);
      if (pathFact && normalized.endsWith(pathFact[1])) return entityToRecord(eid);
    }
    return null;
  }

  // Get all entities where a given attribute matches a value
  function where(filter) {
    return query(filter);
  }

  // Get plan progress from datastore (no file scanning needed)
  function planProgress(planId) {
    const tasks = query({ 'part-of': planId });
    let total = 0, completed = 0, open = 0, deferred = 0;
    for (const t of tasks) {
      if (t.type !== 'task') continue;
      total++;
      if (t.status === 'completed') completed++;
      else if (t.status === 'deferred') deferred++;
      else open++;
    }
    return { total, completed, open, deferred };
  }

  // Get operational records (goals, projects, objectives, plans, tasks, ideas)
  // that are not completed/archived
