function loadRecords() {
  const records = [];
  for (const [type, dir] of Object.entries(RECORD_DIRS)) {
    if (!fs.existsSync(dir)) continue;
    let files;
    try { files = fs.readdirSync(dir).filter(f => f.endsWith('.md')); } catch { continue; }
    for (const f of files) {
      try {
        const filePath = path.join(dir, f);
        const content = fs.readFileSync(filePath, 'utf8');
        const fmEnd = content.indexOf('---', 3);
        if (fmEnd === -1) continue;
        const fm = content.slice(0, fmEnd + 3);

        const get = (key) => {
          const m = fm.match(new RegExp(`^${key}:\\s*"?([^"\\n]+)"?`, 'm'));
          return m ? m[1].trim() : '';
        };

        const id = get('id') || f.replace('.md', '');
        const title = get('title') || get('goal') || id;
        const status = get('status');
        const partOf = get('part-of');

        if (status === 'completed' || status === 'archived') continue;

        const body = content.slice(fmEnd + 3).trim().slice(0, 200);
        const searchText = `${id} ${title} ${get('description')} ${body}`.toLowerCase();
        const relPath = path.relative(REPO_ROOT, filePath).replace(/\\/g, '/');

        records.push({ type, id, title, status, partOf, searchText, relPath });
      } catch { /* skip */ }
    }
  }
  return records;
}","new_string":"// ── Record loading (from datastore) ────────────────────────────────

