 */
function getPlanProgress(planId, allRecords) {
  const tasks = allRecords.filter(r => r.type === 'tasks' && r.partOf === planId);
  // Need to also count completed tasks (which are filtered from allRecords)
  const tasksDir = RECORD_DIRS.tasks;
  let total = 0, completed = 0, open = 0, deferred = 0;
  try {
    const files = fs.readdirSync(tasksDir).filter(f => f.endsWith('.md'));
    for (const f of files) {
      try {
        const content = fs.readFileSync(path.join(tasksDir, f), 'utf8');
        if (!content.includes(`part-of: ${planId}`) && !content.includes(`part-of: "${planId}"`)) continue;
        total++;
        if (content.includes('status: completed')) completed++;
        else if (content.includes('status: deferred')) deferred++;
        else open++;
      } catch { /* skip */ }
    }
  } catch { /* skip */ }
  return { total, completed, open, deferred };
}","new_string":"// getPlanProgress now comes from datastore — see db.planProgress(planId)","replace_all":false}

{"file_path":"c:\Users\emsen\research\operations\engineering\tools\agentic\hooks\compose-environment.js","old_string":"// ── Knowledge graph term lookup ────────────────────────────────────

function searchTerms(keywords) {
  if (!fs.existsSync(GRAPH_PATH)) return [];
  try {
    const graph = JSON.parse(fs.readFileSync(GRAPH_PATH, 'utf8'));
    const entities = graph.entities || [];
    const matches = [];
    for (const entity of entities) {
      if (entity.type !== 'term') continue;
      const name = (entity.title || entity.id || '').toLowerCase();
      for (const kw of keywords) {
        if (kw.length >= 4 && name.includes(kw)) {
          matches.push({ title: entity.title || entity.id, path: entity.path });
          break;
        }
      }
      if (matches.length >= 5) break;
    }
    return matches;
  } catch { return []; }
}","new_string":"// searchTerms now comes from datastore — see db.searchTerms(keywords)","replace_all":false}

