{"file_path":"c:\Users\emsen\research\operations\engineering\tools\agentic\hooks\datastore.js","old_string":"  // Search terms in the graph
  function searchTerms(keywords, limit = 5) {
    const results = [];
    for (const [eid, facts] of byEntity) {
      const typeFact = facts.find(f => f[0] === TYPE);
      if (!typeFact || typeFact[1] !== 'term') continue;
      const titleFact = facts.find(f => f[0] === TITLE);
      const defFact = facts.find(f => f[0] === DEFINES);
      const name = ((titleFact && titleFact[1]) || (defFact && defFact[1]) || '').toLowerCase();
      for (const kw of keywords) {
        if (kw.length >= 4 && name.includes(kw)) {
          const pathFact = facts.find(f => f[0] === PATH);
          results.push({ title: titleFact ? titleFact[1] : '', path: pathFact ? pathFact[1] : '' });
          break;
        }
      }
      if (results.length >= limit) break;
    }
    return results;
  }","new_string":"  // Search terms in the graph — require significant match, not substring noise
  function searchTerms(keywords, limit = 5) {
    const results = [];
    for (const [eid, facts] of byEntity) {
      const typeFact = facts.find(f => f[0] === TYPE);
      if (!typeFact || typeFact[1] !== 'term') continue;
      const titleFact = facts.find(f => f[0] === TITLE);
      const defFact = facts.find(f => f[0] === DEFINES);
      const name = ((titleFact && titleFact[1]) || (defFact && defFact[1]) || '').toLowerCase();
      const nameWords = name.split(/[\s-]+/);
      let hits = 0;
      for (const kw of keywords) {
        // Require keyword >= 5 chars AND either exact word match or >50% of term name
        if (kw.length < 5) continue;
        if (nameWords.some(w => w === kw || (kw.length >= 6 && w.startsWith(kw.slice(0, 6))))) {
          hits++;
        }
      }
      if (hits >= 1) {
        const pathFact = facts.find(f => f[0] === PATH);
        const descFact = facts.find(f => f[0] === DESC);
        results.push({
          title: titleFact ? titleFact[1] : '',
          path: pathFact ? pathFact[1] : '',
          description: descFact ? descFact[1] : '',
          hits,
        });
      }
      if (results.length >= limit * 3) break; // collect extras for sorting
    }
    return results.sort((a, b) => b.hits - a.hits).slice(0, limit);
  }","replace_all":false}

