const fs = require('fs');
const path = require('path');
const { isHookEnabled } = require('./hook-profiles.js');

if (!isHookEnabled('update-datastore', { profiles: 'standard,strict' })) process.exit(0);

const REPO_ROOT = path.resolve(__dirname, '..', '..', '..', '..', '..');
