  'supersedes': { ':db/cardinality': ':db.cardinality/many' },
  'ordering': { ':db/cardinality': ':db.cardinality/many' },
};

const MULTI_ATTRS = new Set(Object.keys(SCHEMA).filter(k => SCHEMA[k][':db/cardinality'] === ':db.cardinality/many'));

function parseFrontmatter(content) {
  const match = content.match(/^---\r?\n([\s\S]*?)\r?\n---/);
  if (!match) return null;
  const fm = {};
  const lines = match[1].split(/\r?\n/);
  let i = 0;
  while (i < lines.length) {
    const kv = lines[i].match(/^(\w[\w-]*):\s*(.*)/);
    if (!kv) { i++; continue; }
    const key = kv[1];
    let val = kv[2].trim();
    if (val === '>-' || val === '>' || val === '|' || val === '|-') {
      const parts = [];
      i++;
      while (i < lines.length && (lines[i].startsWith('  ') || lines[i] === '')) {
        parts.push(lines[i].trim());
        i++;
      }
      fm[key] = parts.filter(Boolean).join(' ');
      continue;
    }
    if (val === '') {
      const items = [];
      i++;
      while (i < lines.length && lines[i].match(/^\s+-\s+/)) {
        items.push(lines[i].replace(/^\s+-\s+/, '').trim());
        i++;
      }
      if (items.length > 0) { fm[key] = items; continue; }
      fm[key] = '';
      continue;
    }
    if ((val.startsWith('"') && val.endsWith('"')) || (val.startsWith("'") && val.endsWith("'"))) {
      val = val.slice(1, -1);
    }
    if (val.startsWith('[') && val.endsWith(']')) {
      try { val = JSON.parse(val); } catch {
        val = val.slice(1, -1).split(',').map(s => s.trim().replace(/^["']|["']$/g, ''));
      }
    }
    fm[key] = val;
    i++;
  }
  return fm;
}

function deriveDomain(rel) {
  const parts = rel.split('/');
  const domainParts = [];
  for (let j = 0; j < parts.length; j++) {
    if (parts[j] === 'domains' && j + 1 < parts.length) {
      domainParts.push(parts[j + 1]);
      j++;
    }
  }
  return domainParts.length > 0 ? domainParts.join('/') : null;
}

function deriveContentRole(rel) {
  const roleMap = [
    ['/terms/', 'term'], ['/texts/', 'text'], ['/plans/', 'plan'],
    ['/session-logs/', 'session-log'], ['/decisions/', 'decision'],
    ['/tasks/', 'task'], ['/projects/', 'project'],
    ['/memory/', 'memory'], ['/triage/', 'triage'],
    ['/skills/', 'skill'], ['/commands/', 'command'], ['/agents/', 'agent'],
  ];
  for (const [pattern, role] of roleMap) {
    if (rel.includes(pattern)) return role;
