/**
 * Compose plan status from the datastore.
 *
 * Queries knowledge-graph.json for all active plans, their tasks,
 * and composes a status table. No file scanning, no inference.
 *
 * Usage: node plan-status.js [plan-id]
 *   No args: show all active plans
 *   With arg: show detail for one plan
 */
const ds = require('../hooks/datastore.js');

const planId = process.argv[2];

try {
  const db = ds.load();
  const allRecords = db.activeRecords();

  if (planId) {
    // Detail for one plan
    const plan = allRecords.find(r => r.id === planId && r.type === 'plans');
    if (!plan) {
      console.log(`Plan "${planId}" not found. Active plans:`);
      allRecords.filter(r => r.type === 'plans').forEach(p => console.log(`  ${p.id}`));
      process.exit(1);
    }

    const progress = db.planProgress(planId);
    const pct = progress.total > 0 ? Math.round((progress.completed / progress.total) * 100) : 0;
    const entity = db.getById(planId);

    console.log(`# ${plan.title}`);
    console.log(`Path: ${plan.path}`);
    console.log(`Status: ${plan.status || 'active'}`);
    if (entity?.goal) console.log(`Goal: ${entity.goal}`);
    if (plan.partOf) console.log(`Project: ${plan.partOf}`);
    console.log(`Progress: ${progress.completed}/${progress.total} (${pct}%) — ${progress.open} open, ${progress.deferred} deferred`);
    console.log('');

    // Show tasks grouped by status
    const tasks = allRecords.filter(r => r.type === 'tasks' && r.partOf === planId);
    // Also get completed tasks from datastore directly
    const allTasks = db.query({ 'part-of': planId }).filter(r => r.type === 'task' || r['content-role'] === 'task');

    const open = allTasks.filter(t => t.status === 'open');
    const completed = allTasks.filter(t => t.status === 'completed');
    const deferred = allTasks.filter(t => t.status === 'deferred');

    if (open.length > 0) {
      console.log(`## Open (${open.length})`);
      for (const t of open) {
        const title = t.title || t.id || '?';
        const goal = t.goal || '';
        console.log(`  ${title}`);
        if (goal) console.log(`    ${goal.slice(0, 120)}`);
      }
      console.log('');
    }

    if (deferred.length > 0) {
      console.log(`## Deferred (${deferred.length})`);
      for (const t of deferred) {
        console.log(`  ${t.title || t.id || '?'}`);
      }
      console.log('');
    }

    if (completed.length > 0) {
      console.log(`## Completed (${completed.length})`);
      for (const t of completed) {
        console.log(`  ${t.title || t.id || '?'}`);
      }
    }
  } else {
    // Summary of all active plans
    const plans = allRecords.filter(r => r.type === 'plans');
    console.log(`# Active Plans (${plans.length})\n`);
    console.log('| Plan | Project | Progress | Open |');
    console.log('|------|---------|----------|------|');

    for (const p of plans.sort((a, b) => (a.partOf || '').localeCompare(b.partOf || ''))) {
      const progress = db.planProgress(p.id);
      const pct = progress.total > 0 ? Math.round((progress.completed / progress.total) * 100) : 0;
      const bar = progress.total > 0 ? `${progress.completed}/${progress.total} (${pct}%)` : 'no tasks';
      console.log(`| ${p.title.slice(0, 50)} | ${p.partOf || '-'} | ${bar} | ${progress.open} |`);
    }
  }
} catch (e) {
  console.error('Error:', e.message);
  process.exit(1);
}
"}

