/**
 * Compose project status from the datastore.
 *
 * Queries knowledge-graph.json for all active projects, their plans,
 * and rolls up task progress. No file scanning, no inference.
 *
 * Usage: node project-status.js [project-id]
 */
const ds = require('../hooks/datastore.js');

const projectId = process.argv[2];

try {
  const db = ds.load();
  const allRecords = db.activeRecords();
  const projects = allRecords.filter(r => r.type === 'projects');

  if (projectId) {
    const proj = projects.find(p => p.id === projectId);
    if (!proj) {
      console.log(`Project "${projectId}" not found. Active projects:`);
      projects.forEach(p => console.log(`  ${p.id}`));
      process.exit(1);
    }

    const entity = db.getById(projectId);
    console.log(`# ${proj.title}`);
    console.log(`Path: ${proj.path}`);
    if (entity?.goal) console.log(`Goal: ${entity.goal}`);
    console.log('');

    // Get plans for this project
    const plans = allRecords.filter(r => r.type === 'plans' && r.partOf === projectId);
    let totalTasks = 0, totalCompleted = 0, totalOpen = 0;

    if (plans.length > 0) {
      console.log(`## Plans (${plans.length})`);
      for (const p of plans) {
        const progress = db.planProgress(p.id);
        totalTasks += progress.total;
        totalCompleted += progress.completed;
        totalOpen += progress.open;
        const pct = progress.total > 0 ? Math.round((progress.completed / progress.total) * 100) : 0;
        const bar = progress.total > 0 ? `${progress.completed}/${progress.total} (${pct}%)` : 'no tasks';
        const pEntity = db.getById(p.id);
        const goal = pEntity?.goal || '';
        console.log(`  ${p.title} [${bar}]`);
        if (goal) console.log(`    ${goal.slice(0, 120)}`);
      }
    } else {
      console.log('No plans assigned to this project.');
    }

    console.log('');
    if (totalTasks > 0) {
      const pct = Math.round((totalCompleted / totalTasks) * 100);
      console.log(`Overall: ${totalCompleted}/${totalTasks} tasks (${pct}%), ${totalOpen} open`);
    }
  } else {
    console.log(`# Active Projects (${projects.length})\n`);
    console.log('| Project | Goal | Plans | Tasks | Done |');
    console.log('|---------|------|-------|-------|------|');

    for (const proj of projects) {
      const plans = allRecords.filter(r => r.type === 'plans' && r.partOf === proj.id);
      let total = 0, done = 0;
      for (const p of plans) {
        const progress = db.planProgress(p.id);
        total += progress.total;
        done += progress.completed;
      }
      const entity = db.getById(proj.id);
      const goal = (entity?.goal || '').slice(0, 60);
      const pct = total > 0 ? ` (${Math.round((done / total) * 100)}%)` : '';
      console.log(`| ${proj.title.slice(0, 35)} | ${goal} | ${plans.length} | ${total} | ${done}${pct} |`);
    }
  }
} catch (e) {
  console.error('Error:', e.message);
  process.exit(1);
}
"}

{"file_path":"c:\Users\emsen\research\operations\engineering\tools\agentic\tools\domain-survey.js","content":"#!/usr/bin/env node
/**
 * Compose a domain survey from the datastore.
 *
 * Shows what terms, texts, and other content exist in a domain,
 * with descriptions. No file scanning.
 *
 * Usage: node domain-survey.js <domain-path>
 *   e.g. node domain-survey.js humanities/philosophy
 *        node domain-survey.js science/math
 */
const ds = require('../hooks/datastore.js');

const domain = process.argv[2];
if (!domain) {
  console.log('Usage: node domain-survey.js <domain-path>');
  console.log('Examples: humanities/philosophy, science/math, engineering/tech/computing');
  process.exit(1);
}

try {
  const db = ds.load();

  // Query all entities in this domain (exact or subdomain)
  const entities = [];
  for (const [eid, facts] of db.byEntity) {
    const domainFact = facts.find(f => f[0] === db.nameToId['in-domain']);
    if (!domainFact) continue;
    const d = domainFact[1];
    if (d !== domain && !d.startsWith(domain + '/')) continue;
    entities.push(db.raw ? null : null); // just need the eid
    const rec = {};
    for (const [a, v] of facts) {
      const name = db.idToName[a];
      if (name) rec[name] = rec[name] ? rec[name] : v;
    }
    rec._eid = eid;
    entities.push(rec);
  }

  // Remove null placeholders
  const items = entities.filter(Boolean);

  console.log(`# Domain: ${domain} (${items.length} entities)\n`);

  // Group by content-role
  const groups = {};
  for (const e of items) {
    const role = e['content-role'] || e.type || 'other';
    if (!groups[role]) groups[role] = [];
    groups[role].push(e);
  }

  for (const [role, entries] of Object.entries(groups).sort((a, b) => b[1].length - a[1].length)) {
    console.log(`## ${role} (${entries.length})`);
    for (const e of entries.slice(0, 15)) {
      const title = e.title || e.defines || e.id || e['file-path']?.replace(/.*\//, '').replace('.md', '') || '?';
      const desc = e.description || e.goal || '';
      if (desc) {
        console.log(`  ${title}: ${desc.slice(0, 120)}`);
      } else {
        console.log(`  ${title}`);
      }
    }
    if (entries.length > 15) console.log(`  +${entries.length - 15} more`);
    console.log('');
  }
} catch (e) {
  console.error('Error:', e.message);
  process.exit(1);
}
"}

{"file_path":"c:\Users\emsen\research\operations\engineering\tools\agentic\tools\briefing.js","content":"#!/usr/bin/env node
/**
 * Compose an organizational briefing from the datastore.
 *
 * Shows: active goals, project health, plans needing attention,
 * and recommended focus. All from frontmatter, no inference.
 *
 * Usage: node briefing.js
 */
const ds = require('../hooks/datastore.js');

try {
  const db = ds.load();
  const allRecords = db.activeRecords();

  const goals = allRecords.filter(r => r.type === 'goals');
  const projects = allRecords.filter(r => r.type === 'projects');
  const plans = allRecords.filter(r => r.type === 'plans');
  const tasks = allRecords.filter(r => r.type === 'tasks');
  const objectives = allRecords.filter(r => r.type === 'objectives');

  console.log(`# Briefing\n`);
  console.log(`${goals.length} goals, ${projects.length} projects, ${plans.length} plans, ${tasks.length} open tasks, ${objectives.length} objectives\n`);

  // Goals
  if (goals.length > 0) {
    console.log('## Goals');
    for (const g of goals) {
      const entity = db.getById(g.id);
      const desc = entity?.goal || entity?.description || g.description || '';
      console.log(`  ${g.title}${desc ? ' — ' + desc.slice(0, 100) : ''}`);
    }
    console.log('');
  }

  // Projects with rolled-up progress
  console.log('## Projects');
  for (const proj of projects) {
    const projPlans = plans.filter(p => p.partOf === proj.id);
    let total = 0, done = 0, open = 0;
    for (const p of projPlans) {
      const progress = db.planProgress(p.id);
      total += progress.total;
      done += progress.completed;
      open += progress.open;
    }
    const pct = total > 0 ? ` ${Math.round((done / total) * 100)}%` : '';
    console.log(`  ${proj.title} — ${projPlans.length} plans, ${total} tasks (${done} done${pct})`);
  }
  console.log('');

  // Plans needing attention: most open tasks first
  const plansByUrgency = plans
    .map(p => ({ ...p, progress: db.planProgress(p.id) }))
    .filter(p => p.progress.open > 0)
    .sort((a, b) => b.progress.open - a.progress.open);

  if (plansByUrgency.length > 0) {
    console.log('## Plans by open tasks');
    for (const p of plansByUrgency.slice(0, 8)) {
      const { completed, total, open } = p.progress;
      const pct = total > 0 ? Math.round((completed / total) * 100) : 0;
      console.log(`  ${p.title} — ${open} open, ${completed}/${total} (${pct}%)`);
    }
    console.log('');
  }

  // Recommended focus: plan with most tasks and some progress (momentum)
  const withMomentum = plansByUrgency.filter(p => p.progress.completed > 0);
  const freshStart = plansByUrgency.filter(p => p.progress.completed === 0 && p.progress.total > 0);

  console.log('## Recommended focus');
  if (withMomentum.length > 0) {
    const top = withMomentum[0];
    console.log(`  Continue: ${top.title} (${top.progress.completed}/${top.progress.total} done, ${top.progress.open} open)`);
  }
  if (freshStart.length > 0) {
    const top = freshStart[0];
    console.log(`  Start: ${top.title} (${top.progress.total} tasks, none started)`);
  }
} catch (e) {
  console.error('Error:', e.message);
  process.exit(1);
}
"}

{"file_path":"c:\Users\emsen\research\operations\engineering\tools\agentic\tools\check-record.js","content":"#!/usr/bin/env node
/**
 * Check a specific record — show all its frontmatter, its relationships,
 * and what records reference it. Composed from the datastore.
 *
 * Usage: node check-record.js <id-or-filename>
 */
const ds = require('../hooks/datastore.js');

const target = process.argv[2];
if (!target) {
  console.log('Usage: node check-record.js <id-or-filename>');
  process.exit(1);
}

try {
  const db = ds.load();
  const entity = db.getById(target);
  if (!entity) {
    console.log(`"${target}" not found in datastore.`);
    process.exit(1);
  }

