/**
 * Create a well-formed record with correct frontmatter at the correct path.
 *
 * Pure function: typed arguments in, file + stdout out. No inference.
 * Validates against the datastore. Composes with other scripts via stdout.
 *
 * Usage:
 *   node create-record.js --type task --id my-task --title "Do the thing" --part-of some-plan --goal "Why this exists"
 *   node create-record.js --type plan --id my-plan --title "Plan name" --part-of some-project --goal "What this achieves"
 *   node create-record.js --type term --id my-term --domain science/math --title "Term name" --description "What it means"
 *
 * Outputs: created file path on stdout (for piping to other tools)
 * Exit 0 on success, 1 on validation failure
 */
'use strict';

const fs = require('fs');
const path = require('path');
const ds = require('../hooks/datastore.js');

const REPO_ROOT = ds.REPO_ROOT;

// ── Argument parsing ──────────────────────────────────────────────

function parseArgs(argv) {
  const args = {};
  for (let i = 0; i < argv.length; i++) {
    if (argv[i].startsWith('--') && i + 1 < argv.length) {
      args[argv[i].slice(2)] = argv[i + 1];
      i++;
    }
  }
  return args;
}

// ── Record type → path mapping ────────────────────────────────────

const TYPE_PATHS = {
  task: 'operations/command/records/tasks',
  plan: 'operations/command/records/plans',
  project: 'operations/command/records/projects',
  objective: 'operations/command/records/objectives',
  goal: 'operations/command/records/goals',
  idea: 'operations/command/records/ideas',
  term: null, // derived from --domain
};

// ── Required fields by type ───────────────────────────────────────

const REQUIRED = {
  task: ['id', 'title', 'part-of', 'goal'],
  plan: ['id', 'title', 'part-of', 'goal'],
  project: ['id', 'title', 'goal'],
  objective: ['id', 'title', 'serves', 'metric'],
  goal: ['id', 'title'],
  idea: ['id', 'title'],
  term: ['id', 'title', 'description'],
};

// ── Validation ────────────────────────────────────────────────────

function validate(args, db) {
  const errors = [];
  const type = args.type;

  if (!type || !REQUIRED[type]) {
    errors.push(`--type must be one of: ${Object.keys(REQUIRED).join(', ')}`);
    return errors;
  }

  for (const field of REQUIRED[type]) {
    if (!args[field]) errors.push(`--${field} is required for type "${type}"`);
  }

  if (type === 'term' && !args.domain) {
    errors.push('--domain is required for type "term" (e.g., science/math, humanities/philosophy)');
  }

  // Check for duplicates
  if (args.id) {
    const existing = db.getById(args.id);
    if (existing) {
      const existingPath = existing['file-path'] || '?';
      errors.push(`Record "${args.id}" already exists at ${existingPath}. Use Edit to update it.`);
    }
  }

  // Check references resolve
  if (args['part-of']) {
    const ref = db.getById(args['part-of']);
    if (!ref) errors.push(`--part-of "${args['part-of']}" not found in datastore`);
  }
  if (args['serves']) {
    const ref = db.getById(args['serves']);
    if (!ref) errors.push(`--serves "${args['serves']}" not found in datastore`);
  }

  return errors;
}

// ── File generation ───────────────────────────────────────────────

function generateFile(args) {
  const type = args.type;
  const lines = ['---'];

  // Standard frontmatter
  lines.push(`id: ${args.id}`);
  lines.push(`title: "${args.title}"`);
  lines.push(`type: ${type}`);

  if (type === 'task' || type === 'plan' || type === 'project' || type === 'objective') {
    lines.push(`status: open`);
  }

  lines.push(`date-created: ${new Date().toISOString().slice(0, 10)}`);

  // Type-specific fields
  if (args['part-of']) lines.push(`part-of: ${args['part-of']}`);
  if (args['serves']) lines.push(`serves: ${args['serves']}`);
  if (args['goal']) lines.push(`goal: "${args.goal}"`);
  if (args['metric']) lines.push(`metric: "${args.metric}"`);
  if (args['description']) lines.push(`description: "${args.description}"`);
  if (args['depends-on']) lines.push(`depends-on:\n  - ${args['depends-on']}`);
  if (args['work-type']) lines.push(`work-type: ${args['work-type']}`);
  if (args['readiness']) lines.push(`readiness: ${args.readiness}`);

  lines.push('---');
  lines.push('');

  // Body
  if (args.goal) {
    lines.push(`**Action:** ${args.title}`);
    lines.push('');
    lines.push(`**Why:** ${args.goal}`);
  }

  return lines.join('\n') + '\n';
}

