 * PreToolUse hook (Write): block direct writes to record directories
 * when a create-record script should be used instead.
 *
 * This is the "use the API, not raw SQL" enforcement.
 * Exit 2 = block, exit 0 = allow.
 */
'use strict';

const RECORD_PATTERNS = [
  {
    pattern: /operations\/command\/records\/tasks\//,
    command: 'node operations/engineering/fars/agentic/tools/create-record.js --type task --id <id> --title "<title>" --part-of <plan> --goal "<goal>"',
    type: 'task',
  },
  {
    pattern: /operations\/command\/records\/plans\//,
    command: 'node operations/engineering/fars/agentic/tools/create-record.js --type plan --id <id> --title "<title>" --part-of <project> --goal "<goal>"',
    type: 'plan',
  },
  {
    pattern: /operations\/command\/records\/projects\//,
    command: 'node operations/engineering/fars/agentic/tools/create-record.js --type project --id <id> --title "<title>" --goal "<goal>"',
    type: 'project',
  },
  {
    pattern: /operations\/command\/records\/objectives\//,
    command: 'node operations/engineering/fars/agentic/tools/create-record.js --type objective --id <id> --title "<title>" --serves <goal-or-project> --metric "<metric>"',
    type: 'objective',
  },
];

let raw = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', chunk => raw += chunk);
process.stdin.on('end', () => {
  try {
    const input = JSON.parse(raw);
    if (input.tool_name !== 'Write') { process.exit(0); return; }

    const filePath = (input.tool_input && input.tool_input.file_path) || '';
    const normalized = filePath.replace(/\\/g, '/');

    // Only block NEW file creation, not overwrites of existing files
    const fs = require('fs');
    if (fs.existsSync(filePath)) { process.exit(0); return; }

    for (const { pattern, command, type } of RECORD_PATTERNS) {
      if (pattern.test(normalized)) {
        process.stderr.write(
          `BLOCKED: Use create-record.js instead of Write to create new ${type} records.\n` +
          `This ensures correct frontmatter, validates references, and updates the datastore.\n\n` +
          `Run in Bash:\n  ${command}\n\n` +
          `Or use the /write-term command for library terms.\n`
        );
        process.exit(2);
        return;
      }
    }
  } catch {}
  process.exit(0);
});
"}

